@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=DM+Mono:wght@400;500&display=swap');
:root{--ink:#eef3ed;--muted:#91a19c;--orange:#f07845;--lime:#c8f16a;--panel:rgba(13,20,22,.86);--line:rgba(210,230,218,.18)}
*{box-sizing:border-box}html,body{height:100%;margin:0;background:#111719;color:var(--ink);font-family:'Barlow Condensed',Arial,sans-serif;overflow:hidden}body{user-select:none;-webkit-user-select:none;touch-action:none}button{font:inherit;color:inherit}#game{display:block;width:100vw;height:100dvh;background:#172024;cursor:crosshair}.grain,.scanlines{pointer-events:none;position:fixed;inset:0;z-index:2}.grain{opacity:.055;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.5'/%3E%3C/svg%3E");mix-blend-mode:screen}.scanlines{opacity:.075;background:repeating-linear-gradient(0deg,transparent 0px,transparent 3px,rgba(0,0,0,.4) 4px)}
.hud{position:fixed;inset:0;pointer-events:none;z-index:4}.topbar{position:absolute;top:24px;left:30px;right:30px;display:flex;align-items:flex-start;justify-content:space-between;text-transform:uppercase;letter-spacing:.11em}.brand{font-size:11px;line-height:1.55;color:var(--muted);font-family:'DM Mono',monospace}.brand b{display:block;font:800 21px/.9 'Barlow Condensed',sans-serif;letter-spacing:.07em;color:var(--ink)}.brand-dot{color:var(--orange);font-size:8px}.objective{text-align:center;min-width:190px}.objective small,.wave-card>small{font:10px 'DM Mono',monospace;letter-spacing:.18em;color:#9daaa4}.objective strong{display:block;font-size:14px;letter-spacing:.16em;margin-top:3px}.status{font:10px 'DM Mono',monospace;color:#9daaa4}.status b{color:#dbe3da;font-weight:500}.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#c8f16a;margin-right:6px;box-shadow:0 0 8px #c8f16a}.status-divider{color:#596663;margin:0 9px}.wave-card{position:absolute;top:113px;left:30px;width:132px;padding:13px 15px 11px;background:linear-gradient(110deg,rgba(15,24,25,.75),rgba(15,24,25,.2));border-left:2px solid rgba(200,241,106,.65)}.wave-number{margin:4px 0 7px;font:30px/.95 'DM Mono',monospace;letter-spacing:-.08em}.wave-number i{font:12px 'DM Mono',monospace;color:#71817c;letter-spacing:0}.wave-track{height:2px;background:#36423e}.wave-track span{height:100%;display:block;background:var(--lime);width:0;transition:width .25s}.hostiles{margin-top:9px;font:9px 'DM Mono',monospace;color:#9daaa4;letter-spacing:.08em}.hostiles b{float:right;color:#f07845;font-weight:500}.hostile-icon{color:#f07845;margin-right:5px}.reticle{position:absolute;left:50%;top:50%;width:26px;height:26px;transform:translate(-50%,-50%);opacity:.85}.reticle i{position:absolute;background:rgba(239,244,234,.9);width:1px;height:6px}.reticle i:nth-child(1){top:0;left:12px}.reticle i:nth-child(2){bottom:0;left:12px}.reticle i:nth-child(3){left:0;top:12px;width:6px;height:1px}.reticle i:nth-child(4){right:0;top:12px;width:6px;height:1px}.reticle b{position:absolute;width:2px;height:2px;left:12px;top:12px;border-radius:50%;background:var(--orange)}.hit-marker{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) scale(.6);font:20px 'DM Mono',monospace;color:#f6eee1;opacity:0;text-shadow:0 0 8px #f07845}.hit-marker.show{animation:hit .22s ease-out}@keyframes hit{0%{opacity:1;transform:translate(-50%,-50%) scale(.65)}100%{opacity:0;transform:translate(-50%,-50%) scale(1.3)}}
.bottom-hud{position:absolute;left:30px;right:30px;bottom:25px;display:grid;grid-template-columns:190px 1fr 180px;align-items:end;gap:26px}.health,.ammo{background:linear-gradient(90deg,rgba(11,17,18,.75),rgba(11,17,18,.1));padding:12px 14px 10px}.hud-label,.ammo-top,.ammo-bottom{display:flex;justify-content:space-between;align-items:center;font:10px 'DM Mono',monospace;letter-spacing:.1em;color:#a8b4ad}.hud-label b{font:14px 'DM Mono',monospace;color:var(--lime)}.meter{height:4px;background:#36413d;margin:8px 0 6px}.meter i{height:100%;display:block;width:100%;background:var(--lime);transition:width .18s,background .18s}.status-caption{font:8px 'DM Mono',monospace;letter-spacing:.14em;color:#798781}.mission-note{display:flex;justify-content:center;align-items:center;gap:10px;padding-bottom:15px;text-align:left}.note-icon{font-size:24px;color:var(--orange)}.mission-note div{display:grid;gap:3px}.mission-note b{font:9px 'DM Mono',monospace;letter-spacing:.13em;color:#e3e7df}.mission-note span:not(.note-icon){font-size:13px;color:#a5b0aa}.ammo{border-right:2px solid var(--orange);text-align:right}.ammo-top{font-size:9px}.ammo-top span:last-child{color:var(--orange)}.ammo-count{font:35px/.95 'DM Mono',monospace;letter-spacing:-.1em;margin:4px 0 5px}.ammo-count b{font-weight:500}.ammo-count span{color:#53615b;font-size:22px;margin:0 8px}.ammo-count i{font-style:normal;color:#9ba8a1;font-size:17px}.ammo-bottom{font-size:8px;letter-spacing:.12em}.ammo-bottom span{color:var(--lime);letter-spacing:.3em}.crosshair-label{position:absolute;left:50%;top:calc(50% + 27px);transform:translateX(-50%);font:8px 'DM Mono',monospace;color:rgba(224,233,225,.55);letter-spacing:.15em}.center-notice{position:absolute;left:50%;top:29%;transform:translate(-50%,-50%);font:700 23px 'Barlow Condensed',sans-serif;letter-spacing:.2em;color:var(--lime);text-shadow:0 2px 12px #111;opacity:0;white-space:nowrap}.center-notice.show{animation:notice 2.2s ease-out}@keyframes notice{0%{opacity:0;transform:translate(-50%,-40%)}15%,75%{opacity:1;transform:translate(-50%,-50%)}100%{opacity:0}}
.overlay,.pause-panel,.end-panel{position:fixed;inset:0;z-index:10;background:radial-gradient(ellipse at 68% 47%,rgba(73,82,69,.15),transparent 40%),linear-gradient(115deg,rgba(10,15,17,.97),rgba(16,23,24,.82));display:flex;align-items:center;padding:clamp(28px,8vw,130px);transition:opacity .45s,visibility .45s}.overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.overlay-grid{position:absolute;inset:0;opacity:.14;background-image:linear-gradient(rgba(220,230,221,.09) 1px,transparent 1px),linear-gradient(90deg,rgba(220,230,221,.09) 1px,transparent 1px);background-size:80px 80px;mask-image:linear-gradient(90deg,#000,transparent 75%)}.briefing{position:relative;width:min(510px,90vw);z-index:1}.eyebrow{font:10px 'DM Mono',monospace;letter-spacing:.17em;color:#aab5ae;display:flex;align-items:center;gap:9px}.orange-bar{display:inline-block;width:18px;height:2px;background:var(--orange)}.eyebrow-code{margin-left:auto;color:#687770}.title-lockup{position:relative;margin:22px 0 6px}.title-lockup h1{font-size:clamp(76px,10.5vw,142px);line-height:.75;letter-spacing:-.035em;font-weight:900;margin:0}.title-lockup h1 em,.end-box h2 em{font-style:normal;color:var(--orange)}.title-mark{position:absolute;left:calc(100% + 5px);bottom:8px;color:#61706a;font:13px 'DM Mono',monospace;writing-mode:vertical-rl;letter-spacing:.15em}.title-mark span{color:var(--orange)}.subtitle{font-size:18px;color:#a8b2ac;letter-spacing:.02em;margin:18px 0 25px}.briefing-rule{height:1px;background:linear-gradient(90deg,rgba(212,224,214,.36),transparent);margin:0 0 17px}.briefing-details{display:flex;gap:clamp(18px,4vw,48px)}.briefing-details div{display:grid;gap:5px}.briefing-details small{font:8px 'DM Mono',monospace;letter-spacing:.16em;color:#77857e}.briefing-details b{font:10px 'DM Mono',monospace;letter-spacing:.06em;font-weight:400}.briefing-details .threat{color:var(--orange)}.start-button,.end-box button{width:205px;height:52px;margin-top:28px;background:var(--lime);color:#18201d;border:0;text-align:left;padding:0 17px 0 20px;display:flex;align-items:center;justify-content:space-between;cursor:pointer;font:800 15px 'Barlow Condensed',sans-serif;letter-spacing:.12em;transition:background .2s,transform .2s}.start-button b,.end-box button b{font-size:23px;font-weight:500}.start-button:hover,.end-box button:hover{background:#e2ff9f;transform:translateY(-2px)}.controls{display:flex;gap:24px;margin-top:25px;align-items:center}.control-row{display:flex;gap:4px;align-items:center}.control-row kbd{font:9px 'DM Mono',monospace;padding:5px 6px;color:#b9c3bc;border:1px solid rgba(211,224,214,.22);background:rgba(190,205,192,.04);min-width:24px;text-align:center}.control-row span{font:8px 'DM Mono',monospace;color:#76837d;letter-spacing:.09em;margin:0 7px 0 3px}.no-audio{font:8px 'DM Mono',monospace;color:#758078;letter-spacing:.12em;margin-top:23px}.no-audio:first-letter{color:var(--orange)}.briefing-side{position:absolute;right:30px;top:50%;height:66%;width:24%;transform:translateY(-50%);border-right:1px solid rgba(212,224,214,.14);border-top:1px solid rgba(212,224,214,.14);border-bottom:1px solid rgba(212,224,214,.14);opacity:.6}.side-cross{position:absolute;right:-5px;top:-11px;color:var(--orange);font:18px 'DM Mono',monospace}.side-vertical{position:absolute;right:22px;top:20px;writing-mode:vertical-rl;font:8px 'DM Mono',monospace;letter-spacing:.17em;color:#8f9b94}.side-coordinates{position:absolute;bottom:18px;left:20px;font:8px 'DM Mono',monospace;letter-spacing:.14em;color:#75827b}.side-coordinates span{color:#c3cdc4;margin-left:12px}
.pause-panel,.end-panel{z-index:12;display:none;align-items:center;justify-content:center;background:rgba(9,14,16,.85);backdrop-filter:blur(8px);padding:24px}.pause-panel.open,.end-panel.open{display:flex}.pause-box,.end-box{width:min(440px,92vw);padding:35px 40px;background:rgba(17,25,26,.95);border:1px solid rgba(212,224,214,.16);border-top:2px solid var(--orange);box-shadow:0 18px 90px rgba(0,0,0,.45)}.pause-box>small,.end-box>small{font:10px 'DM Mono',monospace;letter-spacing:.18em;color:#99a59e}.pause-box h2,.end-box h2{font-size:62px;line-height:.82;letter-spacing:.02em;margin:13px 0}.pause-box h2 span{color:var(--orange)}.pause-box p,.end-box p{font-size:15px;color:#a2ada6}.pause-box button,.end-box button{display:flex;justify-content:space-between;align-items:center;width:100%;height:44px;margin-top:15px;padding:0 14px;border:1px solid rgba(213,225,216,.27);background:transparent;text-align:left;font:600 12px 'DM Mono',monospace;letter-spacing:.08em;cursor:pointer}.pause-box button:first-of-type{background:var(--lime);color:#17201b;border-color:var(--lime)}.pause-box button:hover{border-color:var(--lime)}.pause-foot{font:8px 'DM Mono',monospace;letter-spacing:.13em;color:#687670;margin-top:23px}.end-box{border-top-color:var(--lime)}.end-box h2{font-size:58px}.end-stats{display:grid;grid-template-columns:repeat(3,1fr);margin-top:23px;padding:15px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);gap:10px}.end-stats div{display:grid;gap:6px}.end-stats small{font:7px 'DM Mono',monospace;letter-spacing:.1em;color:#85928b}.end-stats b{font:18px 'DM Mono',monospace;font-weight:400}.end-box button{background:var(--lime);color:#18201d;border:0;font:800 14px 'Barlow Condensed',sans-serif}
.mobile-controls{display:none;position:fixed;z-index:8;inset:auto 0 0;height:175px;pointer-events:none}.stick-zone{pointer-events:auto;position:absolute;left:23px;bottom:27px;width:118px;height:118px;border-radius:50%;border:1px solid rgba(227,235,226,.32);background:rgba(15,23,24,.3);display:grid;place-items:center}.stick-zone:after{content:'';position:absolute;width:68px;height:68px;border:1px solid rgba(227,235,226,.15);border-radius:50%}.stick{position:absolute;z-index:1;width:42px;height:42px;border-radius:50%;background:rgba(200,241,106,.38);border:1px solid rgba(200,241,106,.7);transform:translate(0,0)}.stick-zone span{position:absolute;top:100%;font:8px 'DM Mono',monospace;letter-spacing:.14em;color:#ccd5cd;margin-top:7px}.fire-button,.reload-button{pointer-events:auto;position:absolute;right:25px;bottom:37px;width:76px;height:76px;border-radius:50%;border:1px solid rgba(240,120,69,.8);background:rgba(83,42,30,.52);color:#ffe8d9;font:700 13px 'DM Mono',monospace;letter-spacing:.1em;touch-action:none}.fire-button:active{background:rgba(240,120,69,.7)}.reload-button{right:110px;bottom:47px;width:48px;height:48px;border-color:rgba(220,230,220,.45);background:rgba(16,25,25,.65);font-size:22px}.reload-button small{position:absolute;top:52px;left:50%;transform:translateX(-50%);font:7px 'DM Mono',monospace;white-space:nowrap}.damage-vignette{position:fixed;z-index:3;inset:0;pointer-events:none;opacity:0;background:radial-gradient(ellipse,transparent 42%,rgba(211,50,37,.58) 100%);transition:opacity .15s}.damage-vignette.active{opacity:1}
@media(max-width:700px){.topbar{top:max(14px,env(safe-area-inset-top));left:15px;right:15px}.brand b{font-size:17px}.brand{font-size:9px}.objective{position:absolute;top:58px;left:50%;transform:translateX(-50%);min-width:170px}.objective strong{font-size:12px}.status{font-size:8px}.wave-card{top:103px;left:14px;transform:scale(.82);transform-origin:top left}.bottom-hud{left:12px;right:12px;bottom:14px;grid-template-columns:1fr 1fr;gap:7px}.health,.ammo{padding:8px 10px}.health{grid-column:1;grid-row:1}.ammo{grid-column:2;grid-row:1}.mission-note{display:none}.ammo-count{font-size:27px}.ammo-count i{font-size:13px}.hud-label,.ammo-top{font-size:8px}.ammo-bottom{font-size:7px}.status-caption{font-size:7px}.mobile-controls{display:block}.crosshair-label{display:none}.overlay{padding:30px 24px;align-items:center}.briefing{width:min(510px,100%)}.title-lockup h1{font-size:clamp(72px,19vw,112px)}.title-mark{display:none}.subtitle{font-size:15px;margin:15px 0 19px}.briefing-details{gap:15px}.briefing-details b{font-size:8px}.briefing-details small{font-size:7px}.controls{gap:4px;flex-wrap:wrap;margin-top:19px}.control-row kbd{font-size:8px;padding:4px}.control-row span{font-size:7px;margin-right:4px}.briefing-side{right:10px;width:15%;height:50%;opacity:.27}.eyebrow{font-size:8px}.eyebrow-code{font-size:7px}.no-audio{margin-top:18px}.start-button{margin-top:22px}.pause-box,.end-box{padding:28px 25px}.center-notice{top:28%;font-size:18px}}
@media(min-width:701px) and (pointer:coarse){.mobile-controls{display:block}}

(() => {
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d',{alpha:false});
const $=id=>document.getElementById(id);
const map=[
'####################','#........#.........#','#........#.........#','#..................#','#..##......##......#','#..##..............#','#..................#','#.....####.........#','#.....#..#.........#','#.....#..#.........#','#..................#','#..........##......#','#..................#','####################'];
const W=map[0].length,H=map.length,FOV=Math.PI/3,TAU=Math.PI*2;
let cw=960,ch=540,scale=1,zbuffer=[],last=0,elapsed=0,playing=false,paused=false,finished=false;
const player={x:3.3,y:2.5,a:0,health:100,ammo:30,reserve:180,kills:0,wave:1};
let enemies=[],spawnQueue=[],spawnTimer=0,waveBreak=0,reloading=0,fireCooldown=0,muzzle=0,damageFlash=0,shake=0;
let keys={},pointerDown=false,touchLook=null,stickVector={x:0,y:0},stickTouch=null,moveSpeed=0;
const spawnPoints=[{x:16.5,y:2.5},{x:17.2,y:5.5},{x:14.5,y:10.4},{x:9.5,y:5.5},{x:3.6,y:10.5},{x:16.5,y:11.5},{x:2.5,y:6.5},{x:11.5,y:2.5},{x:6.5,y:11.5}];
let lastFrame=performance.now();
function resize(){const dpr=Math.min(devicePixelRatio||1,1.6);cw=Math.min(1280,Math.floor(innerWidth*dpr));ch=Math.floor(cw/(innerWidth/innerHeight));if(ch>900){ch=900;cw=Math.floor(ch*innerWidth/innerHeight)}canvas.width=cw;canvas.height=ch;canvas.style.width=innerWidth+'px';canvas.style.height=innerHeight+'px';ctx.imageSmoothingEnabled=false;}
addEventListener('resize',resize);resize();
function wall(x,y){const ix=Math.floor(x),iy=Math.floor(y);return iy<0||iy>=H||ix<0||ix>=W||map[iy][ix]==='#'}
function normalize(a){while(a>Math.PI)a-=TAU;while(a< -Math.PI)a+=TAU;return a}
function cast(angle){const dx=Math.cos(angle),dy=Math.sin(angle);let mx=Math.floor(player.x),my=Math.floor(player.y);const ddx=Math.abs(1/(dx||1e-9)),ddy=Math.abs(1/(dy||1e-9));const sx=dx<0?-1:1,sy=dy<0?-1:1;let sideX=(dx<0?player.x-mx:mx+1-player.x)*ddx,sideY=(dy<0?player.y-my:my+1-player.y)*ddy,side=0,steps=0;while(steps++<45){if(sideX<sideY){sideX+=ddx;mx+=sx;side=0}else{sideY+=ddy;my+=sy;side=1}if(my<0||my>=H||mx<0||mx>=W||map[my][mx]==='#')break}let d=side===0?sideX-ddx:sideY-ddy;d=Math.max(.08,d);let hit=side===0?player.y+d*dy:player.x+d*dx;return{d,side,wallX:hit-Math.floor(hit),mx,my,dx,dy}}
function drawWorld(){
 const horizon=ch*.465;
 let sky=ctx.createLinearGradient(0,0,0,horizon);sky.addColorStop(0,'#1b2728');sky.addColorStop(.64,'#3b4540');sky.addColorStop(1,'#73766a');ctx.fillStyle=sky;ctx.fillRect(0,0,cw,horizon);
 // Distant industrial glow and silhouette
 const glow=ctx.createRadialGradient(cw*.72,horizon*.7,2,cw*.72,horizon*.7,cw*.33);glow.addColorStop(0,'rgba(226,148,82,.24)');glow.addColorStop(1,'rgba(226,148,82,0)');ctx.fillStyle=glow;ctx.fillRect(0,0,cw,horizon);
 ctx.fillStyle='#252d2a';ctx.beginPath();ctx.moveTo(0,horizon*.81);for(let x=0;x<=cw;x+=cw/12){let yy=horizon*(.74+Math.sin(x*.021)*.018+Math.cos(x*.009)*.025);ctx.lineTo(x,yy);ctx.lineTo(x,yy+22)}ctx.lineTo(cw,horizon);ctx.lineTo(0,horizon);ctx.fill();
 // floor gradient
 const floor=ctx.createLinearGradient(0,horizon,0,ch);floor.addColorStop(0,'#52534a');floor.addColorStop(.22,'#363a34');floor.addColorStop(1,'#171e1d');ctx.fillStyle=floor;ctx.fillRect(0,horizon,cw,ch-horizon);
 // Perspective lines
 ctx.save();ctx.beginPath();ctx.rect(0,horizon,cw,ch-horizon);ctx.clip();ctx.strokeStyle='rgba(200,204,174,.105)';ctx.lineWidth=1;
 for(let i=-16;i<=16;i++){ctx.beginPath();ctx.moveTo(cw/2+i*3,horizon);ctx.lineTo(cw/2+i*cw*.095,ch);ctx.stroke()}
 for(let n=1;n<14;n++){const yy=horizon+(ch-horizon)*(n*n/169);ctx.beginPath();ctx.moveTo(0,yy);ctx.lineTo(cw,yy);ctx.stroke()}
 ctx.restore();
 const cols=Math.ceil(cw/2);zbuffer.length=cols;
 for(let i=0;i<cols;i++){const sx=i*2+1,angle=player.a+Math.atan((sx-cw/2)/(cw*.5)*Math.tan(FOV/2));const hit=cast(angle),dist=hit.d*Math.cos(angle-player.a);zbuffer[i]=dist;const wallH=Math.min(ch*2,ch/(dist*1.05));let top=horizon-wallH*.53,bottom=top+wallH;
 const edge=hit.wallX<.035||hit.wallX>.965, seam=(Math.floor(hit.wallX*8)%2===0);let shade=Math.max(.22,1-dist/13)*(hit.side?.72:1);const variant=(hit.mx*7+hit.my*13)%3;const base=[[105,111,98],[110,105,90],[91,103,99]][variant];
 const grad=ctx.createLinearGradient(0,top,0,bottom);grad.addColorStop(0,`rgb(${base.map(v=>v*shade*.76|0).join(',')})`);grad.addColorStop(.48,`rgb(${base.map(v=>v*shade|0).join(',')})`);grad.addColorStop(1,`rgb(${base.map(v=>v*shade*.56|0).join(',')})`);ctx.fillStyle=grad;ctx.fillRect(sx,top,2.5,wallH);
 if(edge){ctx.fillStyle=`rgba(15,22,22,${.35+shade*.2})`;ctx.fillRect(sx,top,2,wallH)}
 // panel seams, conduit and occasional warning paint
 if(seam&&dist<12){ctx.fillStyle=`rgba(15,22,21,${.28*shade})`;ctx.fillRect(sx,top+wallH*.13,1,wallH*.72)}
 if(hit.wallX>.34&&hit.wallX<.39&&hit.my%3===0){ctx.fillStyle=`rgba(220,115,58,${.48*shade})`;ctx.fillRect(sx,top+wallH*.14,2,Math.max(3,wallH*.018))}
 if(hit.wallX>.65&&hit.wallX<.69&&hit.mx%4===0){ctx.fillStyle=`rgba(218,204,154,${.15*shade})`;ctx.fillRect(sx,top+wallH*.79,2,Math.max(2,wallH*.012))}
 }
 // subtle ground debris / floor glints
 ctx.save();ctx.globalAlpha=.19;for(let j=0;j<20;j++){const x=((j*197+Math.floor(player.x*32))%cw),y=horizon+(ch-horizon)*((j%9+1)/10);ctx.fillStyle=j%3?'#a1a28b':'#d18a58';ctx.fillRect(x,y,2+(j%4),1)}ctx.restore();
}
function poly(points,fill,stroke){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
function drawBot(e){const rel=normalize(Math.atan2(e.y-player.y,e.x-player.x)-player.a),dist=Math.hypot(e.x-player.x,e.y-player.y);if(Math.abs(rel)>FOV*.72||dist<.25)return;const sx=cw/2+Math.tan(rel)/Math.tan(FOV/2)*cw/2,bi=Math.max(0,Math.min(zbuffer.length-1,Math.floor(sx/2)));if(dist>zbuffer[bi]+.2)return;
